      const row = (x0, z0, x1, z1, ang, pitch, fill) => { const L2 = Math.hypot(x1 - x0, z1 - z0), n = Math.floor(L2 / pitch); for (let i = 0; i <= n; i++) { if (R2() > fill) continue; const t = n ? i / n : 0; farCar(x0 + (x1 - x0) * t, z0 + (z1 - z0) * t, ang + (R2() - 0.5) * 0.05); } };
