        for (let z = 171; z < 213; z += metPitch(3.1)) for (const y of [1.0, 4.7, 8.3]) atlW('winW', [51.82 + (z - 169.16) * 0.0097, z + 1.2], [51.82 + (z - 169.16) * 0.0097, z], y, y + 1.9, [-1, 0, 0]);
