      const P = pr || {}, S = DEFP.st, endZ = kind === 'td' ? FL : spot, gained = Math.round(endZ - los), who = nm(P.int || P.scoop || DEFP.ctl);
      let head = '', sub = '', col = '#2bd46b', line = '', out = null;
      const yd = (n) => (Math.abs(n) === 1 ? '1 yard' : Math.abs(n) + ' yards');
