    const DSTYLE = { c1b: { loss: 1.45, big: 1.2, to: 1.25 }, c3b: { loss: 1.35, big: 1.1, to: 1.3 }, c0: { loss: 1.9, big: 1.45, to: 1.35 }, prev: { slow: 1.2 }, c4: { big: 0.9 } };
