      const cs = clamp(CS + k * (METCALF ? 0.9 : 0.3) + (DRAMA.cpuHot ? 0.08 : 0), 0, 1.25), c = Math.pow(cs, 1.3), toK = clamp(1 - k * (METCALF ? 1.2 : 0.8), 0.2, METCALF ? 3 : 1.8);
