      volcano: ['Eruption', 'Volcano'], arctic: ['Ice Trail', 'Arctic'], desert: ['Sandstorm', 'Desert Storm'], chalkboard: ['Draw It Up', 'Chalkboard'], blueprint: ['By The Plans', 'Blueprint'],
